package io.github.jimbozoomer.jugcraft.botany;

import com.google.gson.JsonElement;
import io.github.jimbozoomer.jugcraft.guide.encyclopedia.*;
import java.util.*;
import net.minecraft.core.registries.*;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.tags.TagKey;
import net.minecraft.world.item.*;

/** One encyclopedia, with native server-reloaded botanical recipes rather than a separate book UI. */
public final class BotanicalGuide {
    private BotanicalGuide(){}
    private static void topic(PageWriter out,String title,String description,String... icons){
        out.heading(Component.literal(title));
        out.fact(Component.literal(description),null,Arrays.stream(icons).map(Jugtania::item).filter(i->i!=Items.AIR).toList());
    }
    public static void write(ServerPlayer player,EncyclopediaRequestPayload request,PageWriter out){
        topic(out,"Start with petals","Find Mystical Flowers in newly explored Overworld terrain, or use Floral Fertilizer on grass. Turn flowers into petals. A Petal Apothecary needs a water bucket, its recipe's petals, and a seed to finish. Use an empty hand to collect the output; sneak with an empty hand to take back offerings.","white_mystical_flower","fertilizer","apothecary_default");
        recipe(out,"petal_apothecary","pure_daisy");
        topic(out,"Livingrock and Livingwood","Place a Pure Daisy with stone or logs immediately around it. Leave the matching blocks in place while they transform. Replacing an input restarts that position's progress. Livingwood makes a Wand of the Forest and your first spreader; Livingrock makes mana pools.","pure_daisy","livingrock","livingwood_log","twig_wand");
        topic(out,"First mana connection","Start with an Endoflame and dropped furnace fuel. Sneak-use the wand on the flower, then use it on a spreader. Repeat from the spreader to a mana pool, keeping each link within 16 blocks. The spreader needs a clear, loaded path. Wand-use a workshop to inspect its mana. Redstone suspends most flowers.","endoflame","mana_spreader","mana_pool");
        recipe(out,"petal_apothecary","endoflame");
        topic(out,"Mana routing and signals","Aim a spreader at a Mana Distributor to share incoming mana between adjacent horizontal pools. It retains overflow until a pool has room. Mana Detectors let bursts pass and emit a four-tick redstone pulse. A Mana Void deliberately destroys incoming mana; placing one directly under a pool allows the pool to discard overflow. Without a void, unaccepted burst mana returns to its source.","mana_distributor","mana_detector","mana_void");
        topic(out,"Spark networks","Use a Spark on a mana pool or Terrestrial Agglomeration Plate. Sparks connect within twelve blocks on the same dye channel, without loading chunks. A plate draws only the mana its complete current recipe needs. Dominant augments draw from standard pools; Recessive pools feed standard or Dispersive pools. Isolated pools remain outside pool-to-pool transfers while still supplying plate recipes. Dispersive pools recharge nearby carried tablets. Each transfer is at most 1,000 mana per tick. Use dyes or augments on the pool; sneak-empty-hand removes the augment, then the spark. Breaking the host returns both.","spark","spark_upgrade_dominant","spark_upgrade_recessive","spark_upgrade_dispersive","spark_upgrade_isolated");
        topic(out,"Workshop timers and moving aim","Hourglasses emit a four-tick redstone pulse. Insert sand for one second per item, red sand for ten seconds, or soul sand for one minute. Mana Powder counts incoming bursts instead. A burst pauses/resumes a sand timer. Wand-use locks its contents; empty-hand use removes unlocked contents. An adjacent hourglass pulse can operate bellows. Bellows face a furnace, accelerating cooking while consuming more fuel; use by hand or a rising redstone pulse, and rotate with the wand. Put a turntable below a spreader to sweep its real aim; wand-use sets speed, sneak-wand reverses, and redstone pauses it.","hourglass","bellows","turntable");
        topic(out,"Infusions and portable mana","Drop the recipe input into a charged pool. Some transformations require an Alchemy or Conjuration Catalyst beneath it. Mana Tablets hold up to 500,000 mana and exchange with pools; sneak-use the wand on a pool to change tablet direction. Carried tablets power botanical equipment, with no research unlock. A tablet can also exchange with a Ley Pylon at 100 mana per ley; sneak-use draws from the pylon.","mana_tablet","manasteel_ingot","mana_diamond","mana_pearl");
        for(String item:List.of("manasteel_ingot","mana_diamond","mana_pearl"))recipe(out,"mana_infusion",item);
        topic(out,"Mana rings, aura and mirrors","Bands of Mana store 500,000 mana; Greater Bands store two million. Charge them through a pool like a tablet, then carry or equip them in a ring slot. Upgrade crafting retains the stored mana. Worn Aura Bands create five mana every 2.5 seconds; Greater Aura Bands do so every half-second, filling carried or equipped mana stores. Sneak-use a Mana Mirror on a pool to bind it. Equipment can draw directly from that real pool while it remains loaded and accessible; multiple mirrors never duplicate its balance.","mana_ring","mana_ring_greater","aura_ring","aura_ring_greater","mana_mirror");
        topic(out,"Construction rods and flight","The Rod of the Lands places dirt for 75 mana; Depths places cobblestone for 150. Highlands can also place floating dirt ahead of you for 150. Seas supplies water for 75, including waterlogging and filling cauldrons. Skies launches you upward for one second and protects the following short descent, for 350 mana; Manaweave strengthens the launch. Hold the Rod of the Molten Core on a smeltable block: ten uninterrupted paid ticks turn it into the furnace recipe’s block output for 300 base mana. Changing targets restarts the operation. Claimed land and unloaded chunks remain protected.","dirt_rod","cobble_rod","skydirt_rod","water_rod","tornado_rod","smelt_rod");
        topic(out,"Terrain rods","Sneak-use Shifting Crust to select the offhand building block (or the clicked block); normal use exchanges a seven-wide plane for 40 mana and one real replacement block per position. Temperance limits it to one. Containers and multipart blocks are excluded, and old drops are returned. Hold Terra Firma to flatten exposed soil around your elevation, paying 55 per changed block. Bifrost creates a temporary three-wide bridge for 750 mana; it lasts 30 seconds, or 48 with Manaweave. It never replaces existing builds. Plentiful Mantle scans loaded ores within 15 blocks (20 with Manaweave), then highlights the nearest 128 privately for eight seconds, costing 3,000 mana.","exchange_rod","terraform_rod","rainbow_rod","divining_rod");
        topic(out,"Combat rods","Hells creates a five-block fire circle lasting fifteen seconds, for 900 mana; it ignites permitted targets rather than spreading fire blocks. Unstable Reservoir fires homing missiles at nearby visible hostiles for 120 mana each. Shaded Mesa holds a permitted non-player entity while you hold use, paying two mana per tick; left-swing throws it. Releasing use or changing items releases the grip. Protected players, claims, blacklisted creatures and ridden entities are excluded.","fire_rod","missile_rod","gravity_rod");
        topic(out,"Botanical armor and customization","Craft the four original armor sets and equip them in normal armor slots; no research is required. Full Manasteel or Elementium saves 10% mana, Terrasteel 20%, and Manaweave 40% on botanical equipment. Terrasteel slowly restores health below normal regeneration hunger and generates a little portable mana. Elementium can summon short-lived retaliating pixies; a complete set adds a debuff, and holding its sword strengthens them. Combine armor with Phantom Ink in a crafting grid to hide its appearance; repeat to restore it. Combine a Terrasteel Helmet with Ancient Wills to add critical-strike effects while wearing the full set. Every piece retains its original supplied model and texture.","manasteel_helmet","elementium_chestplate","terrasteel_helmet","manaweave_chestplate","phantom_ink");
        topic(out,"Ancient botanical treasures","Black Lotus adds 8,000 mana to a pool that already contains mana; Blacker Lotus adds 100,000. Leave room for the complete charge. Overgrowth Seeds found in ancient chests turn Grass Blocks into Enchanted Soil, accelerating the flower above it. Hydroangeas and floating flowers do not receive this acceleration. Breaking Enchanted Soil drops dirt. The Lexicon opens these same encyclopedia chapters; sneak-use it for the flower reference.","black_lotus","blacker_lotus","overgrowth_seed","enchanted_soil","lexicon");
        topic(out,"Runes and stronger materials","Offer the listed ingredients to a Runic Altar and connect a spreader. Once charged, use Livingrock to finish; rune ingredients are retained. A Terrestrial Agglomeration Plate sits above a 3×3 Livingrock/Lapis foundation and consumes 500,000 mana for Terrasteel. Bring enough supply before starting.","runic_altar","rune_mana","terra_plate","terrasteel_ingot");
        recipe(out,"runic_altar","rune_mana");recipe(out,"terra_plate","terrasteel_ingot");
        topic(out,"Trade with Alfheim","Build a five-by-five vertical Livingwood frame: the portal base is the bottom center, corners are omitted, and the 3×3 interior stays clear. Glimmering logs go at the top center and the middle of both sides. Put two Natura Pylons directly above separate mana pools within five blocks. Activation costs 100,000 mana from each pool; trades cost another 250 each. Use the wand to open it, then throw the listed offerings through. This gate trades items; it is not a player travel portal.","alfheim_portal","natura_pylon","elementium_ingot","pixie_dust");
        for(String item:List.of("elementium_ingot","pixie_dust","dragonstone"))recipe(out,"elven_trade",item);
        topic(out,"Reusable botanical brews","Place a Botanical Brewery, insert an empty Vial or Flask first, then its recipe ingredients, and aim a mana spreader at it. Vials hold four drinks; Flasks hold six and cost twice the mana. The last drink returns the empty vessel. Mana and ingredients are consumed only when the complete formula can finish. Allure speeds fishing, Feather Feet protects falls, Soul Cross heals on kills, Emptiness suppresses natural hostile spawning nearby, and Bloodthirst allows nearby monsters to spawn despite light. Existing sanctuary protections still apply. Clear removes active effects.","brewery","vial","flask","brew_vial","brew_flask");
        for(var brew:JugtaniaRecipes.of("brew")){String id=brew.data().get("brew").getAsString().replace("jugcraft:jugtania_","");var spec=BotanicalBrewing.BREWS.get(id);if(spec!=null)out.fact(Component.literal(id.replace('_',' ')+": "+String.join(" + ",brew.ingredients().stream().map(BotanicalGuide::ingredient).toList())+" · "+spec.mana()+" mana per vial"));}
        topic(out,"Incense for a workshop","Use a blank Incense Stick as the brewery container to infuse a single non-instant effect for ten times the vial mana cost. Absorption and mixed-effect brews cannot become incense. Put the infused stick on an Incense Plate and light it. Its area effect reaches permitted players within 32 blocks for sixty times the original brew duration. Water extinguishes and consumes a burning stick. The plate's comparator reads 1 when loaded and 2 while burning.","incense_stick","incense_plate");
        topic(out,"Mana enchanting ritual","Build the obsidian/crying-obsidian base shown below, put a Lapis Block above its center, and arrange six Mana Pylons on Mystical Flowers: two five blocks east/west, and four at offsets (±4, ±3). Place four more Mystical Flowers at the diagonal neighbors of the lapis. The entire layout can rotate ninety degrees. Wand-use the lapis to form the Mana Enchanter. Insert unenchanted equipment, drop compatible enchanted books within two blocks, and wand-use to begin. Books are retained. The displayed mana cost follows enchantment rarity, level, count and treasure status. Attach a spark to receive mana from nearby pool sparks. After charging, infusion takes five seconds. Breaking the pattern reverts the core to lapis and drops its held equipment.","enchanter","mana_pylon","spark");
        topic(out,"Enchanter base, top view","Five rows of obsidian at ground level; dots mean no required block. Rows north to south: .###. / #.#.# / ##### / #.#.# / .###. The center lapis is one block above the middle #. Four inner flowers sit above the empty diagonal positions. Six outer flowers and their pylons extend beyond this base as described above.","livingrock");
        topic(out,"Clearing and gathering","Hold a Horn of the Wild to clear vegetation, a Canopy horn for non-persistent leaves, or a Covering horn for snow. Bergamute shields nearby blocks and animals from these sound-driven actions. Aim mana bursts at Wild/Canopy drums for the same clearing actions. Gathering drums shear up to four eligible animals, accelerate chicken egg timers, and fill buckets/bowls dropped directly beside compatible animals; brown mooshroom stew effects are retained. Claims are checked at every affected location.","horn_grass","horn_leaves","horn_snow","drum_wild","drum_canopy","drum_gathering");
        topic(out,"Botanical signals and weather","An Animated Torch points a redstone output in one direction. Mana bursts toggle, rotate or randomly redirect it; wand-use cycles these modes, while sneak-empty-hand turns it manually. Eye of the Ancients counts nearby animals, with comparator strength equal to animals minus one, capped at fifteen. Ender Overseer emits redstone when someone looks directly at it within 64 blocks; a worn carved pumpkin hides that gaze. Teru Teru Bozu reports rain to a comparator and occasionally clears it. Offer a sunflower to clear rain or a blue orchid for a one-in-ten rain chance.","animated_torch","forest_eye","ender_eye_block","teru_teru_bozu");
        topic(out,"Life and spark automation","Put a Life Imbuer immediately above a spawner and supply mana bursts. It pays six mana per active tick to satisfy the nearby-player requirement; ordinary spawn and collision checks remain. Spark Tinkerers swap their held augment with an adjacent pool's spark on a redstone rising edge. Empty switches remove an augment; the displaced augment stays inside for the next swap.","spawner_claw","spark_changer");
        topic(out,"Cocoons of Caprice","A cocoon hatches after two minutes while its operator and area are available. Emeralds increase the villager chance by five percent each, and chorus fruit similarly favors a shulker, checked first. Both accept at most twenty. Water beside the cocoon selects aquatic creatures. Gaia Spirit guarantees the rare creature table and advances the timer to at least halfway. A blocked hatch waits without consuming the cocoon or rerolling the chosen creature. Baby animals grow normally.","cocoon","life_essence");
        topic(out,"Open Crates and Crafty Crates","Open Crates drop inserted items straight down; power adds a ten-second pickup delay for flower automation. Crafty Crates accept one ingredient per position and craft when every unlocked position is filled. Pattern cards lock unused positions; use the same card again to reset. Placeholders count as empty recipe positions and are returned. When inputs match multiple outputs the crate waits: sneak-wand cycles the output preview, normal wand locks it. Matching future batches retain that choice. Items and recipe remainders eject only into a clear, permitted space underneath. Sneak-empty-hand takes ingredients back.","open_crate","crafty_crate","placeholder","pattern_2_2","pattern_donut");
        topic(out,"Tools without research gates","Manasteel tools mine, till, strip and flatten using their native tool actions. Pickaxes can place carried torches; axes can plant carried saplings. Each prevented durability point costs 60 mana, or 30 for shears and 40 for a Livingwood Bow. Repairing existing damage costs twice that. Without mana they use normal durability. Soulscribe is a durability-only Enderman weapon.","manasteel_pick","manasteel_axe","manasteel_shears","livingwood_bow","soulscribe");
        topic(out,"Elementium utility tools","The pickaxe discards tagged rubble; crouch while mining to retain the secondary stone list. The shovel clears matching gravity-affected blocks up to twelve blocks above and below; crouch to mine one block. The hoe moistens freshly tilled farmland. Hold-use the shears to shear visible permitted animals within twelve blocks, one every five ticks. Protected land remains protected.","elementium_pickaxe","elementium_shovel","elementium_hoe","elementium_shears");
        topic(out,"Advanced tools","Terra Shatterer stores mana fed through a pool and upgrades at 10,000; one million; ten million; one hundred million; and one billion mana. Sneak-use toggles area mining above rank D. Active mode slowly spends the stored charge. Terra Truncator fells connected natural logs and leaves in a bounded, claim-checked job; crouch for a single block. A toggled Stone of Temperance disables tree felling and caps the Shatterer at rank B. Vitreous Pickaxe preserves glass using Silk Touch only for its glass drops. Elementium Axe can drop matching vanilla mob heads, improved by Looting.","terra_pick","terra_axe","temperance_stone","glass_pickaxe","elementium_axe");
        topic(out,"Botanical blades","Terra Blade fires a straight green mana burst on a charged attack or right-click. Starcaller calls falling stars toward the terrain you aim at, sometimes an extra star near a clear midnight. Thundercaller chains damage between visible hostile creatures within eight blocks of each other, with more jumps during thunderstorms. These attacks respect player combat permissions and do not explode terrain.","terra_sword","star_sword","thunder_sword");
        topic(out,"Corporea storage network","Place sparks on your storage and Corporea devices, keeping linked endpoints within eight blocks on each axis. Use exactly one Master Spark and matching dye channels. Networks use loaded inventories only, cap at 128 nodes and do not cross claim permissions or mix different owners. Right-click an Index for a paged item catalogue: left-click retrieves one, right/shift-click a stack. Requests spend actual stored items and leave overflow safely in storage. Creative Sparks are creative-only unlimited template inventories.","corporea_spark","corporea_spark_master","corporea_index");
        topic(out,"Corporea automation","Attach an item frame to a Funnel and rotate it to request 1, 2, 4, 8, 16, 32, 48 or 64 items on each redstone rising edge. A physical buffer retains output until storage below accepts it; hoppers can also extract it. An Interceptor pulses for matching shortages, filtered by attached frames. Adjacent Retainers remember the request and retry on a rising edge; wand-use selects missing-only or whole-request mode. A Crystal Cube samples a held item without consuming it and displays the network count. Empty-hand use retrieves one, sneak-use a stack; wand locks the sample and Phantom Ink hides the number.","corporea_funnel","corporea_interceptor","corporea_retainer","corporea_crystal_cube");
        topic(out,"Botanical accessories","Equip rings, pendants, belts, cloaks and charms in their matching accessory slots; no research is needed. Mantle grants Haste II and spends mana while mining. Chordata sustains underwater conduit and swimming effects. Magnet rings attract reachable permitted drops; crouch or use Solegnolia to disable them. Correction swaps to a better carried botanical mining tool; Far Reach adds 3.5 blocks of building reach. The Great Fairy Ring improves defensive pixie chances. Sashes improve running, stepping and jumping; Planestrider accelerates while moving and resets when you stop. The Girdle resists ordinary and explosion knockback.","mining_ring","water_ring","magnet_ring","swap_ring","reach_ring","travel_belt","knockback_belt");
        topic(out,"Charms, cloaks and pendants","Pyroclast extinguishes burning; Crimson also protects against fire damage. Snowflake freezes water temporarily and permits powder-snow walking; crouch to stop freezing. Third Eye marks nearby hostiles for mana. Infuse a Blood Pendant in a brewery with one eligible non-instant brew for ten times vial cost, then wear it to sustain that effect using portable mana. Invisibility costs two mana per tick. Virtue blocks a hit, Balance halves/reflects one, and Sin retaliates against nearby hostiles; each has a ten-second cooldown. Goddess spends 1,000 mana to preserve terrain around a nearby explosion without cancelling entity damage. Diva can spare a defeated ordinary enemy and turn it against another for a bounded bout; it does not revive bosses or repeatedly farm loot.","lava_pendant","super_lava_pendant","ice_pendant","blood_pendant","holy_cloak","balance_cloak","unholy_cloak","goddess_charm","diva_charm");
        topic(out,"Air movement","Cirrus provides one extra jump; Nimbus provides two. Press jump again while airborne. Dexterous Motion dodges on a quick double-tap of a movement key, once per second on the ground. Flügel Tiara grants one minute of mana-powered flight, recharging while not flying. Double-tap jump to fly, sneak to descend; sneak while falling to glide. Flight spends 35 base mana per tick. Sprint-start dashes have a cooldown. Sneak-use the held Tiara to cycle its original wing styles, including the no-wings style. Shared flight leases preserve other Jugcraft flight providers.","cloud_pendant","super_cloud_pendant","dodge_ring","flight_tiara");
        topic(out,"Mana rails and industry","A Mana Pool Minecart holds one million mana. Put a Mana Pump between its rail and a pool; use the wand to reverse transfer. Redstone pauses the pump. A Mana Fluxfield accepts aimed mana bursts and converts each mana into 3 JE, feeding compatible machines and cables. Its buffer is 3,840 JE. Ghost Rails give permitted carts a short upward spectral hop; Dreamwood stops the hop.","pool_minecart","pump","mana_fluxfield","ghost_rail");
        topic(out,"Light routes","Bind Luminizers with the wand in segments no longer than twenty blocks, with a clear path for the rider. Empty-hand use begins a ride. The Launcher sends occupants into an adjacent linked Luminizer on a rising redstone pulse. Detector relays pulse when passed; Toggle relays stop routes while powered. Foreign pets and other players' permissions are respected.","light_relay","detector_light_relay","toggle_light_relay","light_launcher");
        topic(out,"Guardian of Gaia","Build a flat arena around a beacon, with Gaia Pylons four blocks away on each diagonal and one block above the beacon. Keep the surrounding twelve-block radius and five-block headroom clear. Offer a Terrasteel Ingot to begin. The guardian teleports, marks delayed mines and summons pixies; at low health, endure the summoned waves before the final phase. Only players present when the fight begins participate. Leaving the arena stops participation and an abandoned ritual ends. Offer a Gaia Spirit Ingot for the harder encounter and relic dice.","gaia_pylon","terrasteel_ingot","gaia_ingot","life_essence","dice");
        topic(out,"Bound relics","Each relic belongs to the adventurer who rolled its die. Infinite Fruit feeds you using mana. King's Key conjures its supplied weapon gates, spending mana for each weapon. Eye of the Flugel records destinations for a charged recall. Thor expands eligible tool areas; Odin grants health and specific damage protection. Loki lets you mark a repeat pattern: wear the ring, sneak-click empty-handed to select the origin and offsets, then the origin again to finish. Sneak-place or mine matching blocks to repeat, using real materials and tool wear. The highlighted pattern previews the work.","infinite_fruit","king_key","flugel_eye","thor_ring","odin_ring","loki_ring");
        topic(out,"Shards of Laputa","Use a shard on terrain to lift a bounded island 42 blocks upward. Combine it with Gaia Spirits to increase its tier. Work is saved and gradual, requiring the owner nearby and both ends permitted. Inventories, multipart blocks, fluids and occupied destinations are preserved rather than moved. Sneak-use another shard cancels your current lift; already moved terrain stays in place.","laputa_shard","life_essence");
        topic(out,"Small botanical devices","Plant a petal and bonemeal its sparkles to grow the corresponding tall flower. A Fel Pumpkin placed above two iron bars summons a Blaze that drops powder rather than rods. Water Bowls carry a bucket of water and return their bowl when emptied. A Prism changes passing bursts to its installed lens. Manastorm Charges are destructive: a burst ignites a long, accelerating storm followed by a large finale; claims remain protected.","white_petal","fel_pumpkin","water_bowl","prism","mana_bomb");
        heldRecipes(player,out);
    }
    public static void flowers(ServerPlayer player,EncyclopediaRequestPayload request,PageWriter out){
        topic(out,"Flower controls","Generating flowers send mana to spreaders. Functional flowers draw from a bound pool. Sneak-use the wand to choose a flower, then use the receiver. Workshops only act with their operator's current permission and in loaded areas; many active operations pause while that operator is offline. Miniature flowers provide smaller working areas.","twig_wand","mana_pool");
        topic(out,"Floating flowers and Manastar","Floating flowers retain their normal function while hovering without supporting soil. Pasture seeds change their island appearance; snowballs add snow. The seeds also spread their soil variant over a small permitted patch. Manastar watches the mana pools directly beside it: blue particles show a gain and red particles show a loss over its three-second comparison window.","floating_endoflame","white_floating_flower","grass_seeds","manastar");
        topic(out,"Fuel, water and lava","Endoflame burns dropped furnace fuel. Hydroangeas draws from water and eventually decays. Thermalily consumes lava and requires a cooldown between feedings; feeding too early restarts that wait.","endoflame","hydroangeas","thermalily");
        topic(out,"Food and foliage","Gourmaryllis rewards varied food rather than repeatedly feeding one meal. Kekimurus consumes cake slices. Munchdew eats nearby leaves, then rests; it does not automatically replant a tree.","gourmaryllis","kekimurus","munchdew");
        topic(out,"Experience and color","Rosa Arcana accepts nearby experience orbs, the owner's XP, and enchantments from dropped gear while retaining curses. Spectrolus takes wool or unshorn sheep in its sixteen-color order. Incorrect colors are left alone.","rosa_arcana","spectrolus");
        topic(out,"Advanced generators","Narslimmus consumes naturally spawned slimes. Shulk Me Not needs a shulker and the nearby levitating enemy it is targeting. Rafflowsia rewards variety when consuming other functional/generating flowers, and refuses workshops holding stored mana or items. Entropinnyum absorbs dry, nearly exploding TNT; do not rely on it to make every explosive safe.","narslimmus","shulk_me_not","rafflowsia","entropinnyum");
        topic(out,"Dandelifeon","Arrange Cellular Blocks on the flower's 25×25 horizontal board. Redstone advances the cellular simulation: live cells survive with two or three neighbors, and an empty cell is born with three. Older generations entering the center earn more mana and clear the board. Keep the area loaded and under the flower operator's control.","dandelifeon","cell_block");
        topic(out,"Growing and breeding","Agricarnation accelerates nearby crops. Jaded Amaranthus grows Mystical Flowers. Pollidisiac consumes the actual food needed by nearby animals for breeding or growth; sneak-empty interaction selects adults, young, or both. Fallen Kanade heals its owner, party and owned pets.","agricarnation","jaded_amaranthus","pollidisiac","fallen_kanade");
        topic(out,"Stone and furnaces","Clayconia converts nearby sand blocks into clay balls. Orechid converts nearby stone using weighted ores; Orechid Ignem works with Nether stone in Nether biomes. Marimorphosis changes nearby stone into biome-related metamorphic variants. Exoflame spends mana to heat and accelerate working furnaces, smokers and blast furnaces.","clayconia","orechid","orechid_ignem","marimorphosis","exoflame");
        topic(out,"Gathering and placing","Hopperhock moves nearby dropped items into adjacent sided inventories, using item frames as filters. Sneak-empty interaction selects allow, deny or ignore. Rannuncarpus places dropped BlockItems on blocks matching the sample two blocks below the flower; sneak-empty interaction toggles exact block-state matching. Fresh drops and protected inventories are respected.","hopperhock","rannuncarpus");
        topic(out,"Moving and naming","Daffomill blows items along a clear corridor; sneak-empty interaction rotates it. To bind Spectranthemum's destination, select the flower with the wand, then use a non-pool block: items arrive above it, within 128 loaded blocks, paying distance and stack costs. Bind a pool separately for power. Labellia consumes renamed name tags to name nearby creatures or items.","daffomill","spectranthemum","labellia");
        topic(out,"Defending a workshop","Bellethorn hurts nearby non-player creatures; Dreadthorn targets adult animals. Hyacidus poisons and Medumone slows. Tangleberrie holds creatures inside its edge; Jiyuulia repels. Tigerseye pacifies creepers and makes them avoid players. Heisei Dream briefly turns nearby enemies against each other. Tamed pets and players are excluded from automatic attacks.","bellethorn","dreadthorn","hyacidus","medumone","tangleberrie","jiyuulia","tigerseye","heisei_dream");
        topic(out,"Quiet and underwater work","Bergamute reduces nearby positional sounds and vibration paths. Solegnolia suppresses nearby item magnets. Vinculotus redirects enderman teleports to checked ground near the flower. Bubbell makes a powered underwater air pocket; temporary air restores its saved water after power or source loss.","bergamute","solegnolia","vinculotus","bubbell");
        topic(out,"Loonium encounters","Supply 35,000 mana for an encounter. The surrounding structure determines the supplied encounter and reward tables. Nearby encounter mobs cap further spawning. Defeat the summoned creature to collect its carried reward in place of ordinary mob drops. Peaceful difficulty does not spawn these encounters.","loonium");
        topic(out,"Corporea storage network","Place sparks on your storage and Corporea devices, keeping linked endpoints within eight blocks on each axis. Use exactly one Master Spark and matching dye channels. Networks use loaded inventories only, cap at 128 nodes and do not cross claim permissions or mix different owners. Right-click an Index for a paged item catalogue: left-click retrieves one, right/shift-click a stack. Requests spend actual stored items and leave overflow safely in storage. Creative Sparks are creative-only unlimited template inventories.","corporea_spark","corporea_spark_master","corporea_index");
        topic(out,"Corporea automation","Attach an item frame to a Funnel and rotate it to request 1, 2, 4, 8, 16, 32, 48 or 64 items on each redstone rising edge. A physical buffer retains output until storage below accepts it; hoppers can also extract it. An Interceptor pulses for matching shortages, filtered by attached frames. Adjacent Retainers remember the request and retry on a rising edge; wand-use selects missing-only or whole-request mode. A Crystal Cube samples a held item without consuming it and displays the network count. Empty-hand use retrieves one, sneak-use a stack; wand locks the sample and Phantom Ink hides the number.","corporea_funnel","corporea_interceptor","corporea_retainer","corporea_crystal_cube");
        topic(out,"Botanical accessories","Equip rings, pendants, belts, cloaks and charms in their matching accessory slots; no research is needed. Mantle grants Haste II and spends mana while mining. Chordata sustains underwater conduit and swimming effects. Magnet rings attract reachable permitted drops; crouch or use Solegnolia to disable them. Correction swaps to a better carried botanical mining tool; Far Reach adds 3.5 blocks of building reach. The Great Fairy Ring improves defensive pixie chances. Sashes improve running, stepping and jumping; Planestrider accelerates while moving and resets when you stop. The Girdle resists ordinary and explosion knockback.","mining_ring","water_ring","magnet_ring","swap_ring","reach_ring","travel_belt","knockback_belt");
        topic(out,"Charms, cloaks and pendants","Pyroclast extinguishes burning; Crimson also protects against fire damage. Snowflake freezes water temporarily and permits powder-snow walking; crouch to stop freezing. Third Eye marks nearby hostiles for mana. Infuse a Blood Pendant in a brewery with one eligible non-instant brew for ten times vial cost, then wear it to sustain that effect using portable mana. Invisibility costs two mana per tick. Virtue blocks a hit, Balance halves/reflects one, and Sin retaliates against nearby hostiles; each has a ten-second cooldown. Goddess spends 1,000 mana to preserve terrain around a nearby explosion without cancelling entity damage. Diva can spare a defeated ordinary enemy and turn it against another for a bounded bout; it does not revive bosses or repeatedly farm loot.","lava_pendant","super_lava_pendant","ice_pendant","blood_pendant","holy_cloak","balance_cloak","unholy_cloak","goddess_charm","diva_charm");
        topic(out,"Air movement","Cirrus provides one extra jump; Nimbus provides two. Press jump again while airborne. Dexterous Motion dodges on a quick double-tap of a movement key, once per second on the ground. Flügel Tiara grants one minute of mana-powered flight, recharging while not flying. Double-tap jump to fly, sneak to descend; sneak while falling to glide. Flight spends 35 base mana per tick. Sprint-start dashes have a cooldown. Sneak-use the held Tiara to cycle its original wing styles, including the no-wings style. Shared flight leases preserve other Jugcraft flight providers.","cloud_pendant","super_cloud_pendant","dodge_ring","flight_tiara");
        topic(out,"Mana rails and industry","A Mana Pool Minecart holds one million mana. Put a Mana Pump between its rail and a pool; use the wand to reverse transfer. Redstone pauses the pump. A Mana Fluxfield accepts aimed mana bursts and converts each mana into 3 JE, feeding compatible machines and cables. Its buffer is 3,840 JE. Ghost Rails give permitted carts a short upward spectral hop; Dreamwood stops the hop.","pool_minecart","pump","mana_fluxfield","ghost_rail");
        topic(out,"Light routes","Bind Luminizers with the wand in segments no longer than twenty blocks, with a clear path for the rider. Empty-hand use begins a ride. The Launcher sends occupants into an adjacent linked Luminizer on a rising redstone pulse. Detector relays pulse when passed; Toggle relays stop routes while powered. Foreign pets and other players' permissions are respected.","light_relay","detector_light_relay","toggle_light_relay","light_launcher");
        topic(out,"Guardian of Gaia","Build a flat arena around a beacon, with Gaia Pylons four blocks away on each diagonal and one block above the beacon. Keep the surrounding twelve-block radius and five-block headroom clear. Offer a Terrasteel Ingot to begin. The guardian teleports, marks delayed mines and summons pixies; at low health, endure the summoned waves before the final phase. Only players present when the fight begins participate. Leaving the arena stops participation and an abandoned ritual ends. Offer a Gaia Spirit Ingot for the harder encounter and relic dice.","gaia_pylon","terrasteel_ingot","gaia_ingot","life_essence","dice");
        topic(out,"Bound relics","Each relic belongs to the adventurer who rolled its die. Infinite Fruit feeds you using mana. King's Key conjures its supplied weapon gates, spending mana for each weapon. Eye of the Flugel records destinations for a charged recall. Thor expands eligible tool areas; Odin grants health and specific damage protection. Loki lets you mark a repeat pattern: wear the ring, sneak-click empty-handed to select the origin and offsets, then the origin again to finish. Sneak-place or mine matching blocks to repeat, using real materials and tool wear. The highlighted pattern previews the work.","infinite_fruit","king_key","flugel_eye","thor_ring","odin_ring","loki_ring");
        topic(out,"Shards of Laputa","Use a shard on terrain to lift a bounded island 42 blocks upward. Combine it with Gaia Spirits to increase its tier. Work is saved and gradual, requiring the owner nearby and both ends permitted. Inventories, multipart blocks, fluids and occupied destinations are preserved rather than moved. Sneak-use another shard cancels your current lift; already moved terrain stays in place.","laputa_shard","life_essence");
        topic(out,"Small botanical devices","Plant a petal and bonemeal its sparkles to grow the corresponding tall flower. A Fel Pumpkin placed above two iron bars summons a Blaze that drops powder rather than rods. Water Bowls carry a bucket of water and return their bowl when emptied. A Prism changes passing bursts to its installed lens. Manastorm Charges are destructive: a burst ignites a long, accelerating storm followed by a large finale; claims remain protected.","white_petal","fel_pumpkin","water_bowl","prism","mana_bomb");
        heldRecipes(player,out);
    }
    private static void recipe(PageWriter out,String type,String output){
        for(var r:JugtaniaRecipes.of(type))if(r.output().is(Jugtania.item(output))){describe(out,r);break;}
    }
    private static void heldRecipes(ServerPlayer p,PageWriter out){
        var held=p.getMainHandItem();if(held.isEmpty())return;int shown=0;
        for(String type:List.of("petal_apothecary","mana_infusion","runic_altar","terra_plate","elven_trade"))for(var r:JugtaniaRecipes.of(type)){
            if(!r.output().is(held.getItem())&&r.ingredients().stream().noneMatch(i->io.github.jimbozoomer.jugcraft.nouveau.NouveauRecipes.ingredient(i,held)))continue;
            if(shown==0)out.heading(Component.literal("Recipes involving your held item"));if(++shown>16){out.fact(Component.literal("More matching recipes exist; hold a specific ingredient or result to narrow this list."));return;}describe(out,r);
        }
    }
    private static void describe(PageWriter out,JugtaniaRecipes.Recipe recipe){
        var output=recipe.output();if(output.isEmpty())return;
        var needs=recipe.ingredients().stream().map(BotanicalGuide::ingredient).toList();
        String text=recipe.type().replace('_',' ')+": "+String.join(" + ",needs)+" → "+output.getCount()+" × "+output.getHoverName().getString();
        if(recipe.mana()>0)text+=" · "+recipe.mana()+" mana";
        if(recipe.data().has("catalyst"))text+=" · catalyst: "+recipe.data().get("catalyst");
        out.fact(Component.literal(text),Component.literal(recipe.id()),List.of(output.getItem()));
    }
    private static String ingredient(JsonElement value){
        if(value==null)return "?";
        if(value.isJsonArray())return String.join(" or ",java.util.stream.StreamSupport.stream(value.getAsJsonArray().spliterator(),false).map(BotanicalGuide::ingredient).toList());
        if(value.isJsonPrimitive())return label(value.getAsString());
        var object=value.getAsJsonObject();if(object.has("tag"))return label("#"+object.get("tag").getAsString());
        if(object.has("item"))return label(object.get("item").getAsString());return value.toString();
    }
    private static String label(String id){
        if(id.startsWith("#"))return "any "+id.substring(id.indexOf(':')+1).replace("jugtania_","").replace('_',' ');
        var item=BuiltInRegistries.ITEM.getValue(Identifier.parse(id));return item==Items.AIR?id:new ItemStack(item).getHoverName().getString();
    }
}
